import{c as d,Q as r,j as o,m as a}from"./chunks/framework.rWdQudnF.js";const u=JSON.parse('{"title":"架构师-备考 案例分析-软件工程真题回顾","description":"","frontmatter":{"title":"架构师-备考 案例分析-软件工程真题回顾"},"headers":[],"relativePath":"案例分析/软件工程真题回顾/index.md","filePath":"案例分析/软件工程真题回顾/index.md","lastUpdated":null}'),e={name:"案例分析/软件工程真题回顾/index.md"};function n(s,t,h,g,l,b){return r(),o("div",null,[...t[0]||(t[0]=[a('<h3 id="内聚性排序-高→低-★" tabindex="-1">内聚性排序（高→低）★ <a class="header-anchor" href="#内聚性排序-高→低-★" aria-label="Permalink to &quot;内聚性排序（高→低）★&quot;">​</a></h3><p>功能内聚 &gt; 顺序内聚 &gt; 通信内聚 &gt; 过程内聚 &gt; 时间内聚 &gt; 逻辑内聚 &gt; 偶然内聚</p><h3 id="dfd-数据流图" tabindex="-1">DFD 数据流图 <a class="header-anchor" href="#dfd-数据流图" aria-label="Permalink to &quot;DFD 数据流图&quot;">​</a></h3><p><strong>4 种基本元素</strong>：外部实体、加工（处理）、数据存储、数据流。</p><p><strong>3 种逻辑符号：</strong></p><table tabindex="0"><thead><tr><th>符号</th><th>含义</th></tr></thead><tbody><tr><td><strong>⊕</strong></td><td>异或（互斥产生，不能同时）</td></tr><tr><td><strong>+</strong></td><td>与（同时产生）</td></tr><tr><td>*** **</td><td>或（至少产生一个）</td></tr></tbody></table><p><strong>DFD 加工 3 种逻辑错误</strong>：黑洞（只有输入无输出）、奇迹（只有输出无输入）、灰洞（输入不足以产生输出）。</p><p><strong>平衡原则</strong>：子图输入输出数据流必须与父图对应加工保持一致。</p><blockquote><p>DFD 用于建立<strong>功能模型</strong>；E-R 图用于建立<strong>数据模型</strong>。</p></blockquote><h3 id="逆向工程-4-级别" tabindex="-1">逆向工程 4 级别 <a class="header-anchor" href="#逆向工程-4-级别" aria-label="Permalink to &quot;逆向工程 4 级别&quot;">​</a></h3><table tabindex="0"><thead><tr><th>级别</th><th>内容</th><th>特点</th></tr></thead><tbody><tr><td><strong>实现级</strong></td><td>语法/源代码</td><td>可完全自动（反编译）</td></tr><tr><td><strong>结构级</strong></td><td>程序结构（模块/调用关系）</td><td>自动变换得到</td></tr><tr><td><strong>功能级</strong></td><td>计算逻辑</td><td>需用户指导</td></tr><tr><td><strong>领域级</strong></td><td>业务语义</td><td>需专家规则</td></tr></tbody></table><blockquote><p>用户指导下的搜索与变换方法可导出<strong>功能级和领域级</strong>。</p></blockquote><h3 id="测试覆盖关系" tabindex="-1">测试覆盖关系 <a class="header-anchor" href="#测试覆盖关系" aria-label="Permalink to &quot;测试覆盖关系&quot;">​</a></h3><blockquote><p>条件覆盖与判断覆盖<strong>互不包含</strong>（经典反例：A∨B 仅两个条件真值即可满足条件覆盖，但均使判断为真，未覆盖假分支）。</p></blockquote><p>覆盖强度：<strong>路径覆盖 &gt; 条件/判定覆盖 &gt; 判定覆盖 ? 条件覆盖 &gt; 语句覆盖</strong>（最弱）。</p><table tabindex="0"><thead><tr><th>覆盖方法</th><th>关注点</th></tr></thead><tbody><tr><td><strong>语句覆盖</strong></td><td>每条语句至少执行一次（最弱）</td></tr><tr><td><strong>判断覆盖</strong></td><td>每个判断真/假至少各一次</td></tr><tr><td><strong>条件覆盖</strong></td><td>每个条件真/假至少各一次</td></tr><tr><td><strong>条件/判定组合覆盖</strong></td><td>每个条件真/假 + 整个判定真/假</td></tr><tr><td><strong>路径覆盖</strong></td><td>所有可能执行路径（最强，难以实现）</td></tr></tbody></table><h3 id="设计模式-3-大类" tabindex="-1">设计模式 3 大类 <a class="header-anchor" href="#设计模式-3-大类" aria-label="Permalink to &quot;设计模式 3 大类&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类型</th><th>核心目的</th><th>常见模式</th></tr></thead><tbody><tr><td><strong>创建型</strong></td><td>对象创建机制，隐藏创建细节</td><td>单例、工厂方法、抽象工厂、建造者、原型</td></tr><tr><td><strong>结构型</strong></td><td>类/对象组合成更大结构</td><td>适配器、桥接、组合、装饰、代理、外观、享元</td></tr><tr><td><strong>行为型</strong></td><td>对象间职责分配和通信</td><td>观察者、策略、命令、解释器、迭代器、模板方法、状态、责任链、中介者、备忘录、访问者</td></tr></tbody></table><blockquote><p>装饰模式 = 结构型（非行为型）；观察者 = 行为型（非结构型）；原型 = 创建型。</p></blockquote><h3 id="rup-统一软件开发过程" tabindex="-1">RUP 统一软件开发过程 <a class="header-anchor" href="#rup-统一软件开发过程" aria-label="Permalink to &quot;RUP 统一软件开发过程&quot;">​</a></h3><p><strong>4 阶段</strong>：初始（确定范围）→ 细化（设计体系结构、制订计划）→ 构造（构建产品）→ 移交（交付）。</p><p><strong>核心特征</strong>：<strong>用例驱动</strong>。</p><h3 id="软件复用" tabindex="-1">软件复用 <a class="header-anchor" href="#软件复用" aria-label="Permalink to &quot;软件复用&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类型</th><th>说明</th><th>速记</th></tr></thead><tbody><tr><td><strong>横向重用</strong></td><td>跨不同应用领域重用通用元素（算法、数据结构、UI组件）</td><td>&quot;横向跨行业&quot;</td></tr><tr><td><strong>纵向重用</strong></td><td>同一应用领域内重用特定业务组件或领域模型</td><td>&quot;纵向同一域&quot;</td></tr></tbody></table><p><strong>软件产品线双生命周期</strong>：领域工程（共性资产开发）+ 应用工程（个性系统组装）。</p><p><strong>软件架构复用过程</strong>：开发可复用资产 → 管理可复用资产 → 使用可复用资产。</p><h3 id="_4-1-视图模型" tabindex="-1">4+1 视图模型 <a class="header-anchor" href="#_4-1-视图模型" aria-label="Permalink to &quot;4+1 视图模型&quot;">​</a></h3><table tabindex="0"><thead><tr><th>视图</th><th>关注点</th></tr></thead><tbody><tr><td><strong>逻辑视图</strong></td><td>功能需求（类、模块、关系）</td></tr><tr><td><strong>开发视图</strong></td><td>静态组织结构（包、库、依赖管理）</td></tr><tr><td><strong>进程视图</strong></td><td>并发、同步、通信（运行时行为）</td></tr><tr><td><strong>物理视图</strong></td><td>软件到硬件映射（节点、网络连接）</td></tr><tr><td><strong>场景视图</strong></td><td>用例串联其他视图</td></tr></tbody></table><blockquote><p>&quot;用例视图&quot;非标准说法，标准为&quot;场景&quot;通过用例体现。</p></blockquote><h3 id="软件维护-4-类型" tabindex="-1">软件维护 4 类型 <a class="header-anchor" href="#软件维护-4-类型" aria-label="Permalink to &quot;软件维护 4 类型&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类型</th><th>内容</th></tr></thead><tbody><tr><td><strong>改正性维护</strong></td><td>修复发现的错误或缺陷</td></tr><tr><td><strong>适应性维护</strong></td><td>适应变化的外部环境（新 OS、新硬件）</td></tr><tr><td><strong>完善性维护</strong></td><td>响应用户新需求，扩充功能或提升性能效率</td></tr><tr><td><strong>预防性维护</strong></td><td>改进未来可维护性或可靠性</td></tr></tbody></table><h3 id="其他速记要点" tabindex="-1">其他速记要点 <a class="header-anchor" href="#其他速记要点" aria-label="Permalink to &quot;其他速记要点&quot;">​</a></h3><table tabindex="0"><thead><tr><th>知识点</th><th>速记</th></tr></thead><tbody><tr><td>CMMI 5 级</td><td>初始→已管理→已定义→量化管理→优化</td></tr><tr><td>单元测试依据</td><td><strong>详细设计</strong>（&quot;单元看详设，模块看概设&quot;）</td></tr><tr><td>系统测试依据</td><td><strong>需求分析</strong>（&quot;系统测需求，单元测编码&quot;）</td></tr><tr><td>螺旋模型核心</td><td>强调<strong>风险分析</strong>，每个迭代含风险评估</td></tr><tr><td>Scrum Backlog 排序</td><td>依据<strong>商业价值</strong></td></tr><tr><td>净室软件工程</td><td>形式化方法<strong>正确性验证</strong> + <strong>统计测试</strong></td></tr><tr><td>需求跟踪</td><td>正向：需求→后续；逆向：后续→需求</td></tr><tr><td>SysML 需求图</td><td>7 种关系：包含/扩展/泛化/跟踪/复制/满足/验证</td></tr><tr><td>结构化分析核心</td><td><strong>面向数据流</strong></td></tr><tr><td>UML 参与者的关系</td><td>只能<strong>泛化</strong>（继承），用例才能包扩（包含+扩展）</td></tr><tr><td>AB 测试</td><td>同时段、同特征用户、随机分组、对比不同版本</td></tr></tbody></table><h3 id="uml-用例关系" tabindex="-1">UML 用例关系 <a class="header-anchor" href="#uml-用例关系" aria-label="Permalink to &quot;UML 用例关系&quot;">​</a></h3><table tabindex="0"><thead><tr><th>关系</th><th>适用对象</th></tr></thead><tbody><tr><td><strong>包含</strong> <code>&lt;&lt;include&gt;&gt;</code></td><td>用例之间（必选）</td></tr><tr><td><strong>扩展</strong> <code>&lt;&lt;extend&gt;&gt;</code></td><td>用例之间（可选）</td></tr><tr><td><strong>泛化</strong></td><td>参与者之间 / 用例之间</td></tr></tbody></table><blockquote><p>聚合是类图关系，不属于用例模型。</p></blockquote><h3 id="数据驱动测试" tabindex="-1">数据驱动测试 <a class="header-anchor" href="#数据驱动测试" aria-label="Permalink to &quot;数据驱动测试&quot;">​</a></h3><p>核心思想：<strong>测试数据与测试脚本分离</strong>，数据存储在外部文件（CSV、Excel、XML），脚本从文件读取数据。</p>',38)])])}const c=d(e,[["render",n]]);export{u as __pageData,c as default};
